package com.vandorlabs.neoforge.ramp;
import com.vandorlabs.persistence.RampControllerData;
import com.vandorlabs.neoforge.ModernHousingTags;
import com.vandorlabs.ramp.ControllerPlatform;
import com.vandorlabs.ramp.RampGeometry;
import com.vandorlabs.redstone.ChannelList;
import net.minecraft.nbt.*;
/** Standalone controller choices only. Captured blocks, receipts and journal state never enter this value. */
public record NativeRampSettings(int startHalf,int endHalf,int treadPixels,boolean powerOn,boolean elevator,boolean extend,int speed,boolean matchTextures,int interpolation,int escalator,boolean moat,boolean verticalLayout,int travelAxis,boolean hasDirection,int direction,boolean analogDeployment,ChannelList channels) {
 public NativeRampSettings(int startHalf,int endHalf,int treadPixels,boolean powerOn,boolean elevator,boolean extend,int speed,boolean matchTextures,int interpolation,int escalator,boolean moat,boolean verticalLayout,int travelAxis,boolean hasDirection,int direction,ChannelList channels){this(startHalf,endHalf,treadPixels,powerOn,elevator,extend,speed,matchTextures,interpolation,escalator,moat,verticalLayout,travelAxis,hasDirection,direction,false,channels);}
 public NativeRampSettings {if(Math.abs((long)startHalf)>ControllerPlatform.MAX_OFFSET_HALF_STEPS||Math.abs((long)endHalf)>ControllerPlatform.MAX_OFFSET_HALF_STEPS||treadPixels<1||treadPixels>16||speed<0||speed>2||interpolation<0||interpolation>2||escalator<0||escalator>2||travelAxis<0||travelAxis>2||direction<0||direction>3)throw new IllegalArgumentException("Ramp choices");java.util.Objects.requireNonNull(channels);}
 public static NativeRampSettings defaults(){return new NativeRampSettings(0,-6,8,true,false,false,1,true,0,0,false,false,0,false,0,ChannelList.EMPTY);}
 public static NativeRampSettings read(CompoundTag tag){var data=RampControllerData.read(new ModernHousingTags(tag));boolean left=data.travelAxis==RampGeometry.LEFT;int start=left?-data.startOffset:data.startOffset,end=left?-data.endOffset:data.endOffset;int a=tag.contains("StartOffsetHalfSteps",Tag.TAG_INT)?tag.getInt("StartOffsetHalfSteps"):(start*2),b=tag.contains("EndOffsetHalfSteps",Tag.TAG_INT)?tag.getInt("EndOffsetHalfSteps"):(end*2);if(left){if(tag.contains("StartOffsetHalfSteps",Tag.TAG_INT))a=-a;if(tag.contains("EndOffsetHalfSteps",Tag.TAG_INT))b=-b;}ChannelList channels=ChannelList.of(data.redstoneChannel);if(tag.contains("RedstoneChannels",Tag.TAG_INT_ARRAY))try{channels=ChannelList.of(tag.getIntArray("RedstoneChannels"));}catch(IllegalArgumentException ignored){}return new NativeRampSettings(clamp(a,-32,32),clamp(b,-32,32),data.treadPixels,data.activateOnPower,data.elevator,data.extendSegments,data.speed,data.matchTextures,clamp(tag.getInt("RampInterpolation"),0,2),clamp(tag.getInt("EscalatorMode"),0,2),tag.getBoolean("MoatMode"),tag.getBoolean("RampVerticalLayout"),left?RampGeometry.RIGHT:data.travelAxis,data.hasDirection,Math.abs(data.direction%4),tag.getBoolean("RampAnalogDeployment"),channels);}
 public NativeRampSettings withAnalogDeployment(boolean next){return new NativeRampSettings(startHalf,endHalf,treadPixels,powerOn,elevator,extend,speed,matchTextures,interpolation,escalator,moat,verticalLayout,travelAxis,hasDirection,direction,next,channels);}
 private static int clamp(int n,int min,int max){return Math.max(min,Math.min(max,n));}
 public int resolvedDirection(int blockHorizontalFacing){if(blockHorizontalFacing<2||blockHorizontalFacing>5)throw new IllegalArgumentException("Horizontal travel fallback");return hasDirection?switch(direction){case 0->3;case 1->4;case 2->2;default->5;}:blockHorizontalFacing;}
 public int startOffset(){return startHalf/2;}public int endOffset(){return endHalf<0?-((Math.abs(endHalf)+1)/2):(endHalf+1)/2;}
 public CompoundTag capture(int blockHorizontalFacing){var tag=new CompoundTag();tag.putInt("redstone_trigger",powerOn?1:2);tag.putInt("ramp_start",startOffset());tag.putInt("ramp_end",endOffset());tag.putInt("ramp_start_half",startHalf);tag.putInt("ramp_end_half",endHalf);tag.putBoolean("ramp_vertical_layout",verticalLayout);tag.putBoolean("MoatMode",moat);tag.putInt("ramp_tread_pixels",treadPixels);tag.putInt("ramp_escalator",escalator);tag.putInt("ramp_speed",speed);tag.putInt("ramp_interpolation",interpolation);tag.putBoolean("ramp_lift",elevator);tag.putBoolean("ramp_extend",extend);tag.putInt("ramp_direction",resolvedDirection(blockHorizontalFacing));tag.putInt("ramp_travel",travelAxis);tag.putBoolean("ramp_match_textures",matchTextures);if(channels.size()>1)tag.putIntArray("redstone_channel",channels.toArray());else tag.putInt("redstone_channel",channels.first());return tag;}
 public CompoundTag itemChoices(int blockHorizontalFacing){var tag=new CompoundTag();tag.putBoolean("RampVerticalLayout",verticalLayout);tag.putBoolean("MoatMode",moat);tag.putInt("RampInterpolation",interpolation);tag.putInt("EscalatorMode",escalator);tag.putInt("StartOffset",startOffset());tag.putInt("EndOffset",endOffset());tag.putInt("StartOffsetHalfSteps",startHalf);tag.putInt("EndOffsetHalfSteps",endHalf);tag.putInt("TreadPixels",treadPixels);tag.putBoolean("PowerOn",powerOn);tag.putBoolean("Elevator",elevator);int face=resolvedDirection(blockHorizontalFacing);tag.putInt("Direction",face==3?0:face==4?1:face==2?2:3);tag.putInt("TravelAxis",travelAxis);tag.putBoolean("ExtendSegments",extend);tag.putInt("Speed",speed);tag.putBoolean("MatchTextures",matchTextures);tag.putInt("Channel",channels.first());tag.putIntArray("RedstoneChannels",channels.toArray());return tag;}
 /** Known choice fields only; the enclosing owner retains unrelated and recovery data separately. */
 public void writeChoices(CompoundTag tag){tag.putInt("ControllerVersion",com.vandorlabs.persistence.SaveSchema.Ramp.CONTROLLER_VERSION);tag.putInt("StartOffset",startOffset());tag.putInt("EndOffset",endOffset());tag.putInt("StartOffsetHalfSteps",startHalf);tag.putInt("EndOffsetHalfSteps",endHalf);tag.putInt("Drop",Math.abs(endOffset()));tag.putBoolean("Top",endHalf<0);tag.putInt("TreadPixels",treadPixels);tag.putInt("Segments",(16+treadPixels-1)/treadPixels);tag.putBoolean("ActivateOnPower",powerOn);tag.putBoolean("Slow",speed==2);tag.putBoolean("Elevator",elevator);tag.putBoolean("ExtendSegments",extend);tag.putInt("SpeedMode",speed);tag.putBoolean("MatchTextures",matchTextures);tag.putInt("RampInterpolation",interpolation);tag.putInt("EscalatorMode",escalator);tag.putBoolean("MoatMode",moat);tag.putBoolean("RampVerticalLayout",verticalLayout);tag.putInt("TravelAxis",travelAxis);if(hasDirection)tag.putInt("RampDirection",direction);else tag.remove("RampDirection");tag.putInt("RedstoneChannel",channels.first());tag.putIntArray("RedstoneChannels",channels.toArray());if(analogDeployment)tag.putBoolean("RampAnalogDeployment",true);else tag.remove("RampAnalogDeployment");}

}
